      "achados": [
        {
          "proposicao": "O texto relata movimento de padronização na indústria subsea, incluindo interfaces para ROV e instalação de umbilicais, com adoção complementar por empresas para unificar parâmetros de conexão em alguns equipamentos subsea e facilitar intercâmbio operacional e instalação conjunta entre equipamentos de distintas empresas, além de reduzir custos.",
          "trechos": [
            "E79181dd0ad778d9b:0:699",
            "E79181dd0ad778d9b:699:1398"
